INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(76, 'frFR', 'Salut, $N. Quel est votre compte rendu ? Avez-vous exploré la Mine Veine-de-jaspe ?', 0),
(208, 'frFR', 'Je vois que vous êtes de retour, $gmon grand:m''dame;. Je suis revenu plus d''une fois au camp sur les genoux à cause du roi Bangalash. Accrochez-vous.', 0),
(833, 'frFR', 'Les intrus dos-hirsutes doivent être éloignés de nos terres sacrées, $N.', 0),
(8281, 'frFR', 'Les frappeurs térébrants représentent une menace sérieuse, il faut s''en occuper immédiatement !', 0),
(8304, 'frFR', 'Ne perdez pas de temps, $N !', 0),
(8320, 'frFR', 'Partez dans le désert et trouvez les géoseigneurs du Crépuscule, $N. Revenez me voir quand ils auront été tués.', 0),
(8334, 'frFR', 'Il vaut mieux que vous découvriez les impératifs de la survie, et leurs coûts, dès maintenant. En tant qu’elfe de sang, vous allez devoir vous habituer aux choix difficiles.$B$BPersonne n’a été là pour nous lorsque le Fléau a déchiré nos terres en deux. Nous nous en sommes sortis seuls.', 0),
(8473, 'frFR', 'J’ose à peine vous le demander, $N… est-ce fait ?', 0),
(8475, 'frFR', 'Vous voilà de retour, $N. Avez-vous eu le temps de combattre les morts-vivants le long de la Malebrèche ?', 0),
(8476, 'frFR', 'Vous trouverez Zeb’Watha et Tor''Watha au sud-est d''ici. Revenez me voir lorsque vous aurez tué les trolls.', 0),
(8490, 'frFR', 'Avez-vous réussi à activer la pierre runique, $N ?', 0),
(8892, 'frFR', 'Avez-vous donné une leçon à ces Déshérités ?', 0),
(8894, 'frFR', 'Alors, avez-vous résolu le problème ? Avez-vous diminué le nombre de ces anomalies magiques ? Que vais-je faire si le magistère Ternesoir revient et que ces choses rôdent encore aux environs ?', 0),
(9147, 'frFR', 'Alors, vous avez ce qu’il me faut ? Faites vite, sinon le jeune elfe de sang est cuit !', 0),
(9155, 'frFR', 'Avez-vous déjà accompli votre tâche ?', 0),
(9158, 'frFR', 'Avez-vous terminé le travail que je vous ai confié, $N ?', 0),
(9159, 'frFR', 'Avez-vous terminé le travail que je vous ai confié, $N ?', 0),
(9160, 'frFR', 'Alors, $C, quelles nouvelles d’An’daroth ? Que trament les elfes de la nuit ?', 0),
(9173, 'frFR', 'J’espère que vous revenez pour m''annoncer que la flèche de Coursevent a été nettoyée de l’infection du Fléau ?', 0),
(9192, 'frFR', 'Ce sont de bonnes ou de mauvaises nouvelle, $gmon brave:poupée; ?', 0),
(9274, 'frFR', 'Vous avez fait ce que je vous avais demandé, $N ?', 0),
(9276, 'frFR', 'Comment vous sortez-vous de l''attaque de Zeb''Tela ?', 0),
(9283, 'frFR', 'Finalement, nous allons nous en sortir grâce à votre aide.', 0),
(9294, 'frFR', 'Plus vite vous répandrez le produit neutralisant dans le lac, moins nombreuses seront les mutations provoquées par l’eau irradiée parmi les créatures de la région, dont nous faisons partie !$B$BJe suis désolée que nous ne puissions rien faire pour les pauvres créatures déjà infectées. Si seulement mon équipement de laboratoire était intact !', 0),
(9352, 'frFR', 'Avez-vous découvert quelque chose ? Les elfes de la nuit sont-ils impliqués ?', 0),
(9355, 'frFR', 'Alors, êtes-vous $gparvenu:parvenue; à dégager la route ?', 0),
(9398, 'frFR', 'Heureuse de vous revoir, $N. Avez-vous achevé la besogne que je vous ai confiée ?', 0),
(9399, 'frFR', 'Vous revoilà ! Avez-vous accompli votre mission ?', 0),
(9513, 'frFR', 'Vous faites une bonne chose pour mon peuple, $N.', 0),
(9515, 'frFR', 'Restez aux aguets !', 0),
(9538, 'frFR', 'Le totem émet un bourdonnement grave.', 0),
(9716, 'frFR', 'Vous avez découvert quelque chose, $N ?', 0),
(9720, 'frFR', 'Est-ce fait, $C ?', 0),
(9730, 'frFR', 'Vous voulez qu’on parle de la prime pour Haghazed ? Bon. Est-ce qu’il est mort ? Il n’y a pas grand-chose d’autre à en dire !', 0),
(9747, 'frFR', 'Vous voilà de retour. Kataru et les esclavagistes d’Umbretourbe sont-ils morts ?', 0),
(9785, 'frFR', 'Vous n’avez pas encore parlé aux anciens, $N ?', 0),
(9786, 'frFR', 'Avez-vous observé les ruines de Boha''mu ? Pouvez-vous seulement imaginer à quoi elles ressemblaient du temps de leur splendeur ?', 0),
(9789, 'frFR', 'Les sabots-fourchus de Nagrand sont un beau défi à relever. J’en ai moi-même tué un assez grand nombre.$B$BVous vous en sortez comment ?', 0),
(9791, 'frFR', 'Votre chasse aux Crocs-du-marais a-t-elle été fructueuse ?', 0),
(9804, 'frFR', 'Utilisez les cerises de Nagrand avant de vous aventurer trop profondément dans le lac.', 0),
(9810, 'frFR', 'Le Cercle terrestre apportera son aide de toutes les façons possibles.', 0),
(9817, 'frFR', 'Vous venez chercher la prime pour Fyashe ? Eh bien, c''est la meilleure nouvelle de la journée !', 0),
(9819, 'frFR', 'Eux dormir ?', 0),
(9855, 'frFR', 'Avez-vous déjà appris à calmer les battements de votre cœur ? À rester immobile comme un lac paisible ? À patiemment attendre le bon moment pour frapper votre proie ?', 0),
(9857, 'frFR', 'Je crois que je vais juste rester couché ici un peu plus longtemps. J''irai bientôt mieux.', 0),
(9858, 'frFR', 'J''imagine que...<tousse>... vous ne vous êtes pas encore $goccupé:occupée;...<tousse>... des broutépines ?', 0),
(9862, 'frFR', 'Les esprits de l’air affirment que les Bourbesang cherchent quelque chose au Berceau-de-l''Été...', 0),
(9878, 'frFR', 'Les Bourbesang sont une tribu de Roués malveillants, $N. Ils ressemblent peut-être aux Kurenaï mais ils sont assurément des bêtes sauvages et meurtrières.', 0),
(9901, 'frFR', 'Êtes-vous $gparvenu:parvenue; à traquer Sporailée ?', 0),
(9921, 'frFR', 'Nous n''avons repris Telaar que tout récemment. Nous ne la perdrons pas une nouvelle fois !', 0),
(9922, 'frFR', 'Prenez garde aux élémentaires du bassin, $N.', 0),
(9924, 'frFR', 'Vous l''avez retrouvé ?', 0),
(9925, 'frFR', 'Vous êtes-vous $goccupé:occupée; des rejetons du Vide, $N ?', 0),
(9938, 'frFR', 'Ne perdez pas un instant ! Il faut arrêter Durn !', 0),
(10007, 'frFR', 'Votre attaque a-t-elle rencontré le succès ?', 0),
(10050, 'frFR', 'Je vous ai demandé quelque chose d’absolument terrible, et je le sais. Vous devez comprendre que la plupart de mes hommes refusent de s’approcher des ruines. Les souvenirs et la souffrance sont trop frais, mais nous ne pouvons pas laisser leurs esprits continuer à errer.$B$BPlus ils dureront, plus leurs liens avec leurs anciennes vies s’estomperont, et plus ils deviendront malveillants.', 0),
(10057, 'frFR', 'Avez-vous triomphé de leurs officiers dans les ruines ?', 0),
(10096, 'frFR', 'Comment ? Déjà de retour ? Alors, comment ça s''est passé ?', 0),
(10099, 'frFR', 'J''ai presque peur de poser la question. Comme je vous vois sortir $gvivant:vivante; de la mine, cela ne peut vouloir dire que deux choses : soit vous avez tué cette abomination, soit vous vous êtes $gdégonflé:dégonflée;. Alors, que s''est-il passé ?', 0),
(10159, 'frFR', 'Comment se passent vos efforts pour nettoyer la colline de Roncecroc ?', 0),
(10232, 'frFR', 'J''espère que vous serez de taille à livrer cette bagarre contre la Légion ardente.$B$BIl y a peu de choses que je déteste autant que ceux qui reviennent sur leur parole, ou <toussote> que les gnomes, mais les démons en font très certainement partie !', 0),
(10302, 'frFR', 'Je travaille à une solution qui à mon avis pourrait être efficace sur ces étranges créatures. J''ai juste besoin d''un peu de temps.', 0),
(10303, 'frFR', 'Ils sont trop nombreux... Nous devons en supprimer le plus possible, ou les survivants n''auront aucune chance contre eux.', 0),
(10308, 'frFR', 'Le Consortium désire ardemment supprimer tous les rebelles Zaxxis du Monceau au sud.$B$B$C, si vous souhaitez continuer à vous insinuer dans nos bonnes grâces, retournez là-bas et apportez-moi davantage de leurs insignes d''affiliation.', 0),
(10336, 'frFR', 'Avez-vous déjà tué tous les démons qui infestent les ruines de Farahlon ?', 0),
(10394, 'frFR', 'Ne me dites pas que vous vous dégonflez, $C ! S''ils achèvent la construction de ce camp de forge, vous aurez à vous soucier de bien plus que ces simples ravageurs gangrenés ! Au travail !', 0),
(10396, 'frFR', 'La Légion peut commencer à bombarder la Horde d''une seconde à l''autre, $N ! Il faut que vous détruisiez ces fichus canons !', 0),
(10400, 'frFR', 'Dites-moi, $N, est-ce fait ? Le seigneur-légion a-t-il été vaincu ?', 0),
(10418, 'frFR', 'Avez-vous mis un terme aux souffrances de ces créatures ? Ne vous méprenez pas, j''adore les animaux, mais pas ceux qui mordent la main qui les nourrit et leur offre un abri.', 0),
(10482, 'frFR', 'Les Mâche-les-os apparaissent en grand nombre, $N. Tuez-les ou les gangr‘‘orcs pourraient bien nous submerger !', 0),
(10515, 'frFR', 'Pas de pitié !', 0),
(10701, 'frFR', 'Quoi ? Quoi ?! Soyez $gbref:brève;… il y a tellement de choses à faire ici.$B$BJe voudrais que cet engin décolle un jour, vous comprenez ?', 0),
(10703, 'frFR', 'Revenez me voir quand ces terres sauvages seront assez sûres pour que les caravanes puissent les traverser.', 0),
(10855, 'frFR', 'Avez-vous procédé à ma petite expérience, $N ?', 0),
(10937, 'frFR', 'Le maître de manœuvre est mort ? Hum, mes éclaireurs se seraient trompés ?', 0),
(11129, 'frFR', 'Vous avez trouvé Kyle ?', 0),
(11576, 'frFR', 'Avez-vous pris les relevés que je vous ai demandés, $C ?', 0),
(11605, 'frFR', '<Vous entendez à nouveau la voix lointaine.>$B$BAvez-vous les noms des anciens errants ?', 0),
(11607, 'frFR', 'Qu''en est-il des esprits des innocents ?', 0),
(11617, 'frFR', 'Avez-vous réussi à détruire les plateformes volantes des chasseurs de mages ?', 0),
(11619, 'frFR', 'Avez-vous vaincu Gamel, $C ?', 0),
(11653, 'frFR', 'Z''êtes $gsûr:sûre; que vous l''avez testée sur assez de spécimens ?', 0),
(11730, 'frFR', 'Combien de robots avez-vous réussi à reprogrammer ?', 0),
(11889, 'frFR', 'Vous êtes de retour. Avec de bonnes nouvelles, j''espère ?', 0),
(11904, 'frFR', 'Le minerai, $N, est-il en sécurité ?', 0),
(11913, 'frFR', 'Avez-vous fait ce que je vous ai demandé, $N ?', 0),
(11973, 'frFR', 'Avez-vous pu la libérer de ses liens ?', 0),
(12013, 'frFR', 'Pensez-vous que je sois crédule à ce point ? Arcanimus dévore toujours les âmes de mes frères et sœurs, $C !', 0),
(12035, 'frFR', 'Déjà fini, $N ?', 0),
(12092, 'frFR', 'Nous pourrions tirer un autre avantage à aider les Anciens : ils pourraient envisager d''aider l''Alliance à régler ses problèmes. Et de toute façon, c''est la meilleure chose à faire.$B$BAlors, combien avez-vous pu en renforcer, $C ?', 0),
(12150, 'frFR', 'Avez-vous eu son nom ? Savez-vous qui est ce chef de guerre magnataure ?', 0),
(12166, 'frFR', 'C''est une honte que nous soyons incapables de soigner les ours et les orignaux victimes de la présence du Fléau.$B$BAu moins pouvons-nous enrayer la propagation de la souillure.', 0),
(12168, 'frFR', 'Je sens la proximité d''une chose infecte.$B$BC''est sur vous ! Qu''est-ce donc, $N ?', 0),
(12169, 'frFR', 'Je sens que le haut-sectateur Zangus est toujours vivant.$B$BQuelque chose ne va pas, $N ? Peut-être avez-vous besoin de vous reposer d''abord ?', 0),
(12310, 'frFR', 'Est-ce fait, %N?', 0),
(12520, 'frFR', 'Alors, vous avez maîtrisé ces bêtes ou vous jetez l''éponge ?', 0),
(12525, 'frFR', 'Vous êtes vous $goccupé:occupée; de Ricarnaque et de son garde du corps ?', 0),
(12529, 'frFR', 'Vous encore $gvivant:vivante; ! Les Poings-durs vous mangent pas encore ?$B$BPeut-être ils vous mangent plus tard.', 0),
(12533, 'frFR', 'Vous apprend à chasser ?', 0),
(12536, 'frFR', 'On dit à Zepik que vous êtes $gbon chasseur:bonne chasseuse; même si vous êtes pas Frénécœur.', 0),
(12549, 'frFR', 'Avez-vous mis vos talents à l''épreuve contre les sabres-d''effroi ?', 0),
(12550, 'frFR', 'Comment se passe la traque ?', 0),
(12551, 'frFR', 'Votre tableau de chasse est rempli ?', 0),
(12603, 'frFR', 'Vous avez mis vos compétences à l''épreuve ?', 0),
(12620, 'frFR', 'Vous êtes-vous $goccupé:occupée; des sectateurs, $N ?', 0),
(12637, 'frFR', 'Oui, $R?', 0),
(12638, 'frFR', 'Oui, $R?', 0),
(12645, 'frFR', 'Ne me faites pas languir, $N... Alors, qu''est-ce que ça a donné ?', 0),
(12680, 'frFR', 'Vous ne voulez pas passer votre vie à marcher, pas vrai ?', 0),
(12733, 'frFR', 'Avez-vous réussi le défi de la mort ?', 0),
(12742, 'frFR', 'Alors, ça fait quel effet ?', 0),
(12743, 'frFR', 'Alors, ça fait quel effet ?', 0),
(12744, 'frFR', 'Alors, ça fait quel effet ?', 0),
(12745, 'frFR', 'Alors, ça fait quel effet ?', 0),
(12746, 'frFR', 'Alors, ça fait quel effet ?', 0),
(12747, 'frFR', 'Alors, ça fait quel effet ?', 0),
(12748, 'frFR', 'Alors, ça fait quel effet ?', 0),
(12749, 'frFR', 'Alors, ça fait quel effet ?', 0),
(12805, 'frFR', 'Avez-vous récupéré l''énergie des élémentaires, $N ?', 0),
(12842, 'frFR', 'Ne perdez pas de temps, $N. Nous sommes au bord de l’apocalypse !', 0),
(12865, 'frFR', 'Ces oiseaux sont loyaux envers nous depuis longtemps... On s''entend très bien.', 0),
(12874, 'frFR', 'Vous r''venez me trouver. Mais revenez-vous $gvictorieux:victorieuse; ?', 0),
(12957, 'frFR', 'Avez-vous libéré les esclaves des Forge-foudre ?', 0),
(12986, 'frFR', 'Revenez-vous avec le savoir que je cherche, $R ?', 0),
(13318, 'frFR', 'Oui, $C?', 0),
(13323, 'frFR', 'Oui, $C?', 0),
(13352, 'frFR', 'Oui, $C?', 0),
(13353, 'frFR', 'Oui, $C?', 0),
(13354, 'frFR', 'Oui, $C?', 0),
(13414, 'frFR', 'Oui, $C?', 0),
(13592, 'frFR', 'Avez-vous mis vos forces à l''épreuve ?', 0),
(13643, 'frFR', 'Vous êtes-vous $grendu:rendue; sur les tombes des combattants tués ?', 0),
(13662, 'frFR', 'Vous avez monté les barreaux de l''échelle de la Confrérie, $R. Nous commençons à avoir de vous une opinion favorable. Voilà un bel exploit !$B$BSi vous souhaitez travailler d''avantage pour gagner davantage de notre respect, écoutez bien.$B$BIl est possible de raffiner le flux embrasé en ajoutant simplement un résidu de sombrefer au mélange. On trouve des résidus de sombrefer dans les Profondeurs de Rochenoire.$B$BApportez-moi tous ceux que vous trouverez !', 0),
(13671, 'frFR', 'Avez-vous mis vos forces à l''épreuve en combattant le Fléau ?', 0),
(13679, 'frFR', 'Avez-vous affronté votre défi ?', 0),
(13680, 'frFR', 'Avez-vous affronté votre défi ?', 0),
(13682, 'frFR', 'Avez-vous vaincu le raid du Culte des damnés ?', 0),
(13749, 'frFR', 'Avez-vous mis vos forces à l''épreuve ?', 0),
(13760, 'frFR', 'Avez-vous mis vos forces à l''épreuve ?', 0),
(13789, 'frFR', 'Avez-vous mis vos forces à l''épreuve ?', 0),
(13791, 'frFR', 'Avez-vous mis vos forces à l''épreuve ?', 0),
(13810, 'frFR', 'Avez-vous mis vos forces à l''épreuve ?', 0),
(13813, 'frFR', 'Avez-vous mis vos forces à l''épreuve ?', 0),
(13828, 'frFR', 'Avez-vous parlé à Jeran Boisclos, et vous êtes-vous entraîné au combat monté à courte distance ?', 0),
(13829, 'frFR', 'Avez-vous parlé à Jeran Boisclos, et vous êtes-vous entraîné au combat monté à courte distance ?', 0),
(13835, 'frFR', 'Vous êtes-vous $gentraîné:entraînée; à utiliser le brise-bouclier ?', 0),
(13837, 'frFR', 'Avez-vous maîtrisé l''utilisation de la charge ?', 0),
(13851, 'frFR', 'Avez-vous combattu aux côtés des croisés, dans la cour des Ossements ?', 0),
(13861, 'frFR', 'Avez-vous combattu l''ennemi dans la cour des Ossements ?', 0),
(13862, 'frFR', 'Avez-vous combattu l''ennemi dans la cour des Ossements ?', 0),
(13863, 'frFR', 'Avez-vous combattu l''ennemi dans la cour des Ossements ?', 0),
(13864, 'frFR', 'Avez-vous combattu l''ennemi dans la cour des Ossements ?', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(24815, 'frFR', 'Pour expier les pêchés que j''ai commis en tant que chevalier de la mort du roi-liche, je me suis consacré à la création d''anneaux de grande puissance que nos frères et sœurs peuvent utiliser dans notre lutte.$B$BVous vous êtes $grévélé un allié:révélée une alliée; de valeur dans notre combat contre le Fléau, $N. Comme votre dévouement demeure, je peux améliorer la conception originelle de l''anneau.$B$BChoisissez votre voix avec soin. Changer d''opinion aura un prix.', 0);
